input.newString:
function frame(now){let dt=Math.min(.04,(now-last)/1000||0);last=now;update(dt);render()}
function startGame(){mode='playing';score=0;batCount=0;lives=3;speed=19;spawnTimer=.8;items=[];lane=0;jumpY=jumpV=slide=invuln=shake=world=0;$('overlay').classList.add('hidden');$('hud').classList.add('show');$('mobile').classList.add('show');$('title').innerHTML='THE DARK<br><em>KNIGHT</em>';}
function endGame(){mode='over';$('hud').classList.remove('show');$('mobile').classList.remove('show');$('title').innerHTML='GOTHAM<br><em>NEEDS YOU</em>';$('message').innerHTML=`Patrol over. You scored <strong style="color:#f3c65e">${score.toLocaleString()}</strong> and recovered <strong style="color:#f3c65e">${batCount}</strong> batarangs. The night is not over yet.`;$('start').textContent='RUN IT BACK';$('overlay').classList.remove('hidden')}
$('start').addEventListener('click',startGame);
function act(action){if(mode!=='playing')return;if(action==='left')lane=clamp(lane-1,-1,1);if(action==='right')lane=clamp(lane+1,-1,1);if(action==='jump'&&jumpY===0&&slide<=0)jumpV=1.48;if(action==='slide'&&jumpY<.3)slide=.72}
addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowleft','arrowright','arrowup','arrowdown',' ','a','d','w','s'].includes(k))e.preventDefault();if(mode!=='playing'){if(k==='enter'||k===' ')startGame();return}if(k==='arrowleft'||k==='a')act('left');if(k==='arrowright'||k==='d')act('right');if(k==='arrowup'||k==='w'||k===' ')act('jump');if(k==='arrowdown'||k==='s')act('slide');if(k==='escape'){mode='paused';$('message').textContent='Take a breath, Dark Knight. Gotham can wait a moment.';$('start').textContent='RESUME PATROL';$('overlay').classList.remove('hidden');$('hud').classList.remove('show');$('mobile').classList.remove('show')}});
$('overlay').addEventListener('click',e=>{if(mode==='paused'&&e.target===$('start')){mode='playing';$('overlay').classList.add('hidden');$('hud').classList.add('show');$('mobile').classList.add('show');$('start').textContent='BEGIN PATROL'}});
document.querySelectorAll('.ctrl').forEach(button=>{button.addEventListener('pointerdown',e=>{e.preventDefault();act(button.dataset.action)})});let touchStart=null;canvas.addEventListener('touchstart',e=>{if(e.touches.length)touchStart={x:e.touches[0].clientX,y:e.touches[0].clientY}},{passive:true});canvas.addEventListener('touchend',e=>{if(!touchStart||mode!=='playing')return;const t=e.changedTouches[0],dx=t.clientX-touchStart.x,dy=t.clientY-touchStart.y;if(Math.max(Math.abs(dx),Math.abs(dy))>26){if(Math.abs(dx)>Math.abs(dy))act(dx<0?'left':'right');else act(dy<0?'jump':'slide')}touchStart=null},{passive:true});
requestAnimationFrame(frame);
})();
</script>
</body>
</html>

